-- GENERATED by `wfj generate` from data/gossip/gossip-06.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["060237f54f44a291"] = { "Il posatoio delle viverne è in cima alla scalinata del totem, al centro del paese.", "." },
  ["060496c12b8e2643"] = { "Ti affetto!", "." },
  ["06062700b6bc58dd"] = { "⟦Southshore=Riva del Sud⟧ pagherà col sangue!", "." },
  ["0606e29d9eea3b05"] = { "Il dipinto, {name}. Hai il dipinto?", "." },
  ["061d199e3d71ef22"] = { "Le stelle di quest'epoca si piegano verso nuovi percorsi, fari di speranza e di forza per le ere a venire.", "." },
  ["062595a0d7e4edfa"] = { "Andatevene, creature immonde! Quelli come voi non hanno posto in questo mondo.", "." },
  ["062c28ce672a9f57"] = { "Prima le ⟦Westfall=Marche Occidentali⟧, poi tutta ⟦Stormwind=Roccavento⟧!", "." },
  ["062e8f5f698b1547"] = { "Ehm... io dispiace che attaccato te, capo. Tu non uccidi me, per favore, va bene!? Tu ora re, e io aiuto fare tuo tributo più bello!", "." },
  ["063898e0e86dc8c2"] = { "Noi viviamo e moriamo, e la terra resta, eterna, indifferente al nostro passaggio. Perciò la terra non può appartenerci, {name}. Siamo noi ad appartenere a lei. Per questo proteggiamo la terra: senza di essa non possiamo sperare di sopravvivere.", "." },
  ["063b9a5d77eb043d"] = { "Conserva il sapere e la parola, e perfino l'autonomia per svolgere compiti per te. Che cosa hai fatto, esattamente?", "." },
  ["063d2bdb71ee9ca4"] = { "(Snif, snif) Lo senti? Non lo ADORI anche tu, l'odore del grasso?", "." },
  ["0641274e8474bffb"] = { "Il Pilastro Orientale accetta cristalli blu, gialli e verdi.\n\nSi concentra sull'energia che si può creare usando i cristalli blu come fonte principale di potere. Ci sono due effetti possibili: uno conferisce un bonus allo Spirito e l'altro crea uno scudo che infligge danni.\n\nForza del Cristallo richiede cristalli blu e verdi. Ti darà un aumento dello Spirito.\n\nSpira del Cristallo richiede cristalli blu e gialli. Creerà uno scudo che infligge danni a chi ti attacca.", "." },
  ["064258d83f2f8c5c"] = { "Archibald quello che cerchi. Lui fuori da negozio di armi su anello interno di ⟦War Quarter=Quartiere della Guerra⟧.", "." },
  ["064ebf80c38e1a0c"] = { "Ce l'abbiamo fatta! Quae, ce l'abbiamo fatta!", "." },
  ["0655027adde1df95"] = { "Shadra, fai di me il tuo avatar!", "." },
  ["0655668af051df8b"] = { "Sarebbe saggio spiegarti fin dove si spingono i nostri nemici pur di nascondersi sotto il nostro naso.\n\nSappi questo prima di tutto: il nostro nemico è il ⟦Shadow Council=Concilio dell'Ombra⟧. Qualunque compito ti affidi, chiunque ti chieda di combattere, tieni sempre a mente questo semplice fatto.\n\nNel Concilio esistono molti culti, ma solo per nascondere le sue azioni agli sciocchi.\n\nGruppi come le ⟦Burning Blade=Lame Ardenti⟧, l'Argus Wake e la ⟦Searing Blade=Lama Rovente⟧ sono tutti strumenti del Concilio. Considerali un'unica cosa.", "." },
  ["065729f80e2c43c2"] = { "Qualcuno vuole fare una pausa? Peccato! Al lavoro, zucconi!", "." },
  ["06587abe93d7f7c2"] = { "Ecco fatto. Una nuova infornata di bombe accecanti!", "." },
  ["0659b80136ed9b38"] = { "Uff! Ecco un altro carico di provviste, Harlan. Devono vendere come il pane!", "." },
  ["0659bd0dec07e61b"] = { "Intrusi!", "." },
  ["065d55b0c7a5d7f9"] = { "Questa maledizione ci è stata scagliata addosso per un semplice medaglione. ⟦Lord Valthalak=Sire Valthalak⟧ sa davvero come serbare rancore.\n\nCi sforzeremo di trovare i pezzi mancanti, sperando di farcela prima di fare una fine prematura. Ma prima pensiamo alla tua ricompensa.", "." },
  ["0663eca114ae585a"] = { "Touché...", "." },
  ["068164b17643f77c"] = { "Hai i due pettorali corazzati e i guanti di ⟦Turtle Scale=Scaglie di Tartaruga⟧? E non dimenticare la vite selvaggia!\n\nGià con i primi schemi impariamo che i fondamenti della forma si trasferiscono bene a indumenti più difficili. Anche se sono oggetti diversi, la forma dei pettorali corazzati di ⟦Turtle Scale=Scaglie di Tartaruga⟧ ti prepara ai dettagli necessari per fare una veste di Cuoio Selvatico.\n\nMan mano che procedi con le lezioni, le abilità che ti insegno diventeranno arte.", "." },
  ["0682a1b5f00fb9d7"] = { "Salve di nuovo, {name}. Pensavi che ti avrei scordato?\n\nSapevo che non l'avresti pensato. Sei <un/una> {class} <sveglio/sveglia>, che riconosce una persona dalla memoria perfetta quando la vede.", "." },
  ["0689cdf0d03b58da"] = { "Temeva che il suo potere si stesse indebolendo, che presto persino noi, le ultime delle sue preziose gemme dell'anima, saremmo svanite e morte.", "." },
  ["0689f189ee903c38"] = { "Se cerchi un volo per tornare a ⟦Thunder Bluff=Picco del Tuono⟧, dovresti parlare con il mio collega tauren, ⟦Bunthen Plainswind=Bunthen Vento Piano⟧.", "." },
  ["0693787e5f26ae60"] = { "Sì, l'ho fatto, comandante.", "." },
  ["069b6300a5b567fe"] = { "Opzione del banchiere", "." },
  ["069f0c630f182ff5"] = { "Siamo sotto attacco!", "." },
  ["06aaaa188d6ea9ce"] = { "Grazie per l'ottimo pasto, tesoro, ma devo tornare davanti al bancone.", "." },
  ["06b2c11045494dce"] = { "⟦Astaia=Kirolla⟧ ha pescato tesori curiosi nelle lunghe ere che ha passato a pescare. Perché non vai da lei alla Tradesman's terrace e ti fai mostrare qualcuno di quei tesori?", "." },
  ["06b9647bbaa70a1f"] = { "State indietro! Fate spazio! L'infernale avrà bisogno di molto spazio!", "." },
  ["06c0723aefca2beb"] = { "Atten-ti! Tutto il materiale bellico per ⟦Ahn'Qiraj=Ahn'qiraj⟧ è stato contato ed è in viaggio verso la ⟦Cenarion Hold=Fortezza Cenariana⟧, <signore/signora>! Mi dicono che l'ultima parte dovrebbe arrivare in meno di un giorno. Una volta fatto, e quando qualcuno suonerà quel gong laggiù per aprire i cancelli, vi garantisco che daremo a quegli insetti una battaglia coi fiocchi!", "." },
  ["06c1a7bca59d31c2"] = { "L'ultima volta ho visto l'anziano Meadowrun alla Weeping Cave, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "." },
  ["06c9191cca1698df"] = { "Eppure pensi che recuperare il Brandicenere possa in qualche modo cambiare le sorti della battaglia? Lascia che ti sveli un piccolo segreto, comandante: il potere del Brandicenere veniva dall'uomo che lo impugnava... Io c'ero, comandante. L'ho visto bruciare legioni di non morti nel fuoco della giustizia prima ancora di sguainare la lama. Ahimè, la tua conoscenza della storia è... lacunosa.", "." },
  ["06db52419a836ab8"] = { "BANG! BANG! BANG! Sto potenziando il carro!!!", "." },
  ["06db847f31014fd0"] = { "Mancano solo due minuti! Siamo a metà strada, ma non abbassate la guardia!", "." },
  ["06e18fddc23286f6"] = { "Due parole: boa d'arcanite.", "." },
  ["06e6f9ed252a3b55"] = { "Eraka no Kimbul\n\nDio delle Tigri, Signore delle Bestie, Re dei Felini, Rovina della Preda\n\nUeetay no Mueh'zala\n\nDio della Morte, Padre del Sonno, Figlio del Tempo, Amico della Notte.", "." },
  ["06f634464c7f1228"] = { "Bersaglio perso....riprendo gli schemi di ricerca Delta", "." },
  ["06f6dfe56b55fb51"] = { "Era ora che qualcuno ammazzasse quel disgraziato.", "." },
  ["06f7e5348a8f8f1d"] = { "La capitana Balinda Stonehearth è caduta!\n\nAttaccate l'⟦Horde=Orda⟧! Vendicate la capitana Stonehearth!", "." },
  ["06fa027342f3fb48"] = { "Kel'Thuzad? Se conosci quel nome, allora forse hai letto davvero il libro che ti ho mandato a prendere.\n\nPurtroppo, la tua risposta è sbagliata.", "." },
  ["06fa1bef00fe13a9"] = { "Se riesci a completare un Mazzo dei Portali, riceverai in premio una carta di Lunacupa superiore: la Carta di Lunacupa: Distorsione Fatua. Questa carta di tanto in tanto riporterà il tuo spirito nel tuo corpo dopo la morte e ti rimetterà in sesto.", "." },
  ["06fb0952e00de5f0"] = { "Ero ancora giovane, appena adolescente tra i tauren, ma sapevo che chi affrontava le battaglie per la nostra libertà era ben protetto dalle vesti che portano il mio nome.", "." },
  ["06fc3285120185fe"] = { "Muori! Quelli come te non hanno posto nella ⟦Alterac Valley=Valle d'Alterac⟧!", "." },
  ["06fdff837e3b68f3"] = { "2ª catena, prima risposta. PWNED~", "." },
})
